package app.streamnest;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import org.json.*;import java.util.*;
final class HomeSearchRegression {
 static Bundle run(Instrumentation test)throws Exception{Context c=test.getTargetContext();WatchSync.pending=true;WatchSync.testPairingCode="";
 try{List<Catalog.Title> pool=new ArrayList<>();for(String kind:new String[]{"movies","shows","animes"})for(int n=0;n<28;n++)pool.add(Catalog.parse(new JSONObject().put("imdb","tt"+(80000+pool.size())).put("title","Moon "+kind+" "+n),kind));HomeLibrary.cached=pool;HomeLibrary.cachedAt=System.currentTimeMillis();HomeSearch.testProvider=(kind,page,q)->{if(kind.equals("shows"))throw new Exception("offline fixture");return Collections.emptyList();};
 MainActivity a=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1200);
 test.runOnMainSync(()->{for(View v:HomeRegression.collect(a.getWindow().getDecorView()))if("Search titles".equals(String.valueOf(v.getContentDescription())))v.performClick();HomeRegression.check(a.search.getVisibility()==View.VISIBLE,"Search icon did not show field directly");a.search.setText("Moon");a.search.onEditorAction(EditorInfo.IME_ACTION_SEARCH);});
 for(int n=0;n<100&&(a.homeSearchPending||a.homeSearchPool.isEmpty());n++)Thread.sleep(150);test.waitForIdleSync();
 test.runOnMainSync(()->{HomeRegression.check(a.homeTab&&a.homeQuery.equals("Moon"),"Search left Home");HomeRegression.check(a.homeSearchFailed,"Partial source failure was not reported");StringBuilder textBuilder=new StringBuilder();for(View v:HomeRegression.collect(a.content))if(v instanceof TextView)textBuilder.append(((TextView)v).getText()).append(" ");String text=textBuilder.toString();for(String kind:new String[]{"Movies","Series","Anime"})HomeRegression.check(text.contains(kind),"Missing mixed category "+kind);HomeRegression.check(text.contains("Moon movies")&&text.contains("Moon shows")&&text.contains("Moon animes"),"Mixed matches missing");});
 final int[] before={0};test.runOnMainSync(()->{before[0]=a.generation;a.homeQuery="New query";a.publishHomeSearch(before[0]-1,"Moon",1,6,pool,false,false,false);});test.waitForIdleSync();test.runOnMainSync(()->{HomeRegression.check(a.homeQuery.equals("New query"),"Stale query overwrote state");a.exitApp();});Thread.sleep(600);test.runOnMainSync(()->{HomeRegression.check(a.homeQuery.isEmpty()&&a.homeTab,"Back did not restore Home");a.finish();});Bundle b=new Bundle();b.putString("result","PASS: direct Home search, mixed results, independent service failure, stale response guard and clear");return b;
 }finally{HomeSearch.testProvider=null;WatchSync.pending=false;WatchSync.testPairingCode=null;HomeLibrary.clear();}}
}
